import math
import time

import firebase_admin  # type: ignore[import-untyped]
import firebase_admin.auth as _fb_auth  # type: ignore[import-untyped]
import firebase_admin.credentials as _fb_creds  # type: ignore[import-untyped]
from google.auth.credentials import AnonymousCredentials
from google.auth.exceptions import GoogleAuthError
import firebase_admin.exceptions as _fb_errors  # type: ignore[import-untyped]

FIREBASE_PROJECT = setting("FIREBASE_PROJECT_ID")
firebase_emulator = local_override("FIREBASE_AUTH_EMULATOR_HOST")


class LocalFirebaseCredential(
    _fb_creds.Base,  # type: ignore[misc,no-any-unimported]
):
    """Credential for the isolated Firebase emulator."""
    def get_credential(self) -> Credentials:
        """Get credential."""
        return AnonymousCredentials()  # type: ignore[no-untyped-call]


firebase_app = firebase_admin.initialize_app(
    LocalFirebaseCredential() if firebase_emulator else None,
    options={"projectId": FIREBASE_PROJECT},
    name=APPLICATION,
)


def authenticate(request: Request) -> Identity:


    """Authenticate."""
    try:
        claims = TypeAdapter(dict[str, object]).validate_python(_fb_auth.verify_id_token(bearer(request), app=firebase_app, check_revoked=True), strict=True)
        now = time.time()
        times: dict[str, float] = {}
        for key in ("exp", "iat", "auth_time"):
            value = claims.get(key)
            if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value):
                raise ValueError("invalid token time claim")
            times[key] = float(value)
        if times["exp"] <= now or times["iat"] > now or times["auth_time"] > now:
            raise ValueError("expired or invalid token time claims")
    except (_fb_auth.InvalidIdTokenError, _fb_auth.ExpiredIdTokenError, _fb_auth.RevokedIdTokenError, _fb_auth.UserDisabledError, _fb_auth.UserNotFoundError, ValueError, KeyError, TypeError) as exc:
        raise unauthorized() from exc
    except (_fb_errors.FirebaseError, GoogleAuthError) as exc:
        raise HTTPException(status_code=503, detail="authentication provider unavailable") from exc
    return validated_identity(claims.get("uid"), claims.get("role", "reader"))
def close_firebase() -> None:
    """Close firebase."""
    firebase_admin.delete_app(firebase_app)


CLOSERS.append(close_firebase)
